const {chromium}=require('playwright');
(async()=>{const b=await chromium.launch({executablePath:process.env.CHROME_EXECUTABLE || undefined,headless:true});const p=await b.newPage({viewport:{width:1440,height:1000}});let errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.argv[2]||'http://127.0.0.1:8767/modular-proofs.html');await p.waitForSelector('.node');await p.getByRole('button',{name:'Proof step 3',exact:true}).click();if(!(await p.locator('#detail').innerText()).includes('determinant'))throw Error('CM lesson');await p.getByRole('button',{name:'Next question',exact:true}).click();await p.locator('#all').click();if(await p.locator('.node').count()!==11)throw Error('bundle count');await p.getByRole('button',{name:'Expand this bundle in graph',exact:true}).click();if(await p.locator('.module-node').count()<3)throw Error('visual expansion');await p.locator('.module-node').first().click();await p.getByRole('button',{name:'Expand imports in graph',exact:true}).click();if(await p.locator('.module-node').count()<1)throw Error('recursive import graph');await p.locator('#all').click();await p.locator('#integer').click();if(await p.locator('.node').count()!==8)throw Error('CM route count');await p.locator('#all').click();await p.locator('#detail summary').first().click();await p.locator('#detail .module').first().click();await p.getByText('Expand the complete Lean source',{exact:true}).click();if(!(await p.locator('#detail pre').last().innerText()).includes('latticeJMap'))throw Error('source snapshot');await p.locator('#detail button').first().click();await p.locator('#detail summary').nth(1).click();await p.getByLabel('Filter source modules').fill('LatticeJInvariant');await p.getByRole('button',{name:'ComputableAnalysis.ModularForms.LatticeJInvariant',exact:true}).click();await p.locator('#fit').click();await p.locator('#zin').click();await p.locator('#error').click();if(!(await p.locator('#detail').innerText()).includes('EC163.deficit_bounds'))throw Error('current exponential API bridge');if(await p.getByRole('link',{name:'Read the checked CM exponential bridge and axiom audit',exact:true}).getAttribute('href')!=='modular-exponential-foundation-audit.txt')throw Error('bridge audit link');await p.locator('#detail summary').first().click();await p.getByRole('button',{name:'ComputableAnalysis.ModularForms.CMExponentialFoundation163',exact:true}).click();await p.getByText('Expand the complete Lean source',{exact:true}).click();if(!(await p.locator('#detail pre').last().innerText()).includes('compoundInterest_bounds'))throw Error('current CM bridge source');await p.locator('#all').click();await p.screenshot({path:'/tmp/modular-graph-desktop.png',fullPage:true});await p.setViewportSize({width:390,height:844});await p.locator('#all').click();await p.screenshot({path:'/tmp/modular-graph-mobile.png',fullPage:true});if(errors.length)throw Error(errors.join('\n'));console.log('PASS: bundles, route filtering, source expansion, transitive filtering, zoom, current exponential API and source, desktop/mobile; no JS errors.');await b.close()})().catch(e=>{console.error(e);process.exit(1)});
